INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64306235', 64306235, 'analyze_legacy', 'Kementerian Energi Dan Sumber Daya Mineral', 'central', 'POLITEKNIK ENERGI DAN MINERAL AKAMIGAS', 'Belanja Barang', 'Barang', 'Pengadaan Langsung', 'Jawa Tengah, Blora (Kab.)', 338800000, 'January 2026', 'APBN - BADAN LAYANAN UMUM (F)', 1, 1, '1 Paket', '1. Buku Wisuda ( 400, eks, @ 185050 ); 2. Perlengkapan wisuda (selembang figura wisudawan terbaik, masker, hand sanitizer) ( 2, pkt, @ 2700000 ); 3. Snack Rapat Biasa JAWA TENGAH ( 150, OK, @ 15000 ); 4. Banner ( 3, bh, @ 400000 ); 5. Makan Rapat Biasa JAWA TENGAH ( 60, OK, @ 38000 ); 6. Makan Rapat Koordinasi Tingkat Menteri/Eselon I/Setara ( 450, OK, @ 110000 ); 7. Snack Rapat Koordinasi Tingkat Menteri/Eselon I/Setara ( 450, OK, @ 49000 ); 8. Dokumentasi Video ( 1, pkt, @ 40900000 ); 9. suvenir wisudawan (cincin wisuda) ( 280, bh, @ 500000 ); 10. Spanduk ( 3, bh, @ 400000 );', '1. Buku Wisuda ( 400, eks, @ 185050 ); 2. Perlengkapan wisuda (selembang figura wisudawan terbaik, masker, hand sanitizer) ( 2, pkt, @ 2700000 ); 3. Snack Rapat Biasa JAWA TENGAH ( 150, OK, @ 15000 ); 4. Banner ( 3, bh, @ 400000 ); 5. Makan Rapat Biasa JAWA TENGAH ( 60, OK, @ 38000 ); 6. Makan Rapat Koordinasi Tingkat Menteri/Eselon I/Setara ( 450, OK, @ 110000 ); 7. Snack Rapat Koordinasi Tingkat Menteri/Eselon I/Setara ( 450, OK, @ 49000 ); 8. Dokumentasi Video ( 1, pkt, @ 40900000 ); 9. suvenir wisudawan (cincin wisuda) ( 280, bh, @ 500000 ); 10. Spanduk ( 3, bh, @ 400000 );', 140000000, 'high', 'Terdapat indikasi pengeluaran seremonial yang berlebihan, khususnya suvenir wisudawan berupa cincin untuk 280 orang dengan nilai total sangat besar. Dalam konteks penggunaan dana publik, pemberian cenderamata bernilai tinggi kepada peserta wisuda kurang esensial terhadap fungsi pendidikan inti dan berpotensi menimbulkan pemborosan. Komponen dokumentasi video juga relatif tinggi dan layak dicermati lebih lanjut.', NULL, NULL, 3, 1, 1, 1, 1, 1473479);
