INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64328055', 64328055, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'Balai Monitor Spektrum Frekuensi Radio Kelas II Manado', 'Pemeliharaan Alat Monitoring Balmon Manado 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Utara, Minahasa (Kab.)', 100000000, 'May 2026', 'APBN - PNBP (D)', 1, 1, '6 Unit', 'Pemeliharaan Peralatan dan Mesin brupa : -Pemeliharaan Perangkat SMFR Transportable 4 Paket -Pemeliharaan Perangkat dan Pendukung SMFR', '1.Pemeriksaan Rutin:Memeriksa kondisi fisik perangkat pendukung seperti UPS, rack server, konektor, kabel, AC ruangan, grounding, dan perangkat pelindung petir.Memverifikasi konektivitas jaringan internal antar perangkat. 2.Pemeliharaan Preventif:Pembersihan perangkat dari debu dan kotoran yang dapat mengganggu sirkulasi udara dan kinerja pendinginan.Update firmware dan software pendukung yang digunakan dalam sistem monitoring. 3.Kalibrasi dan Pengujian:Melakukan pengujian fungsi perangkat pendukung seperti power supply, inverter, dan switch jaringan.Melakukan kalibrasi pada alat ukur yang relevan bila diperlukan. 4.Perbaikan Ringan:Penanganan gangguan minor yang ditemukan saat pemeriksaan, seperti penggantian kabel rusak,kipas pendingin, atau port jaringan yang bermasalah.Penguatan konektor dan pengaturan ulang konfigurasi perangkat pendukung. 5.Pencatatan dan Dokumentasi 6.Koordinasi dengan Pihak Terkait', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1476149);
