INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64348532', 64348532, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'KONSULTAN SENIOR PROGRAMMER PENGEMBANGAN BACKEND SISTEM INFORMASI KRISNA', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 644000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Memberikan masukan dan rekomendasi teknis strategis kepada Direktorat Alokasi Anggaran Pembangunan Pusat dan Daerah Bappenas dalam perumusan kebutuhan penyempurnaan dan pengembangan arsitektur backend Sistem Informasi KRISNA, baik untuk Pemerintah Pusat maupun Pemerintah Daerah. Merancang dan menetapkan desain arsitektur back end tingkat lanjut (advanced back end architecture) KRISNA dan teknologi pendukung yang menjamin skalabilitas, keamanan, dan keberlanjutan sistem. Berperan sebagai lead technical backend specialist dalam kolaborasi dengan Konsultan Senior System Analyst dan tim pengembangan lainnya, khususnya dalam menerjemahkan kebutuhan kebijakan perencanaan dan penganggaran ke dalam rancangan solusi backend yang kompleks, terintegrasi, dan berkelanjutan. Melakukan analisis mendalam dan perancangan fitur backend strategis dan kompleks, termasuk fitur lintas-sub sistem yang mendukung sinkronisasi perencanaan dan penganggaran Pemerintah Pusat dan Pemerintah Daerah. Menyiapkan dan memelihara database tahun anggaran baru untuk masing-masing sub-sistem KRISNA, baik terkait Pemerintah Pusat dan Pemerintah Daerah; Melakukan evaluasi teknis menyeluruh (technical assessment) terhadap performa, keamanan, skalabilitas, dan maintainability backend KRISNA, serta menyusun rekomendasi refactoring dan peningkatan arsitektur berbasis kebutuhan jangka panjang sistem. Memastikan sistem berjalan dengan lancar tanpa kendala dan memperbaiki dengan cepat jika ada permasalahan sistem, serta memperbaiki rules aplikasi agar sistem berjalan dengan efisien dengan cara melakukan proses refactor secara berkala dan sesuai kebutuhan; Menganalisis, merancang, serta implementasi backend (pengembangan API, layanan, business logic, integrasi dengan sistem lain, autentikasi/otorisasi, keamanan), termasuk integrasi sistem, volume data, keamanan, dan performa pada Sistem Informasi KRISNA, baik terkait Pemerintah Pusat dan Pemerintah Daerah; Melakukan reviu kode (code review) terhadap hasil kerja Konsultan Lainnya untuk memastikan kualitas, keamanan, konsistensi standar pengembangan, dan kepatuhan terhadap pola arsitektur Sistem Informasi KRISNA; Mengembangkan integrasi dan interkoneksi Sistem Informasi KRISNA dengan sistem informasi lainnya baik di lingkungan Kementerian PPN/Bappenas ataupun Kementerian/Lembaga lainnya sesuai dengan kebutuhan; Menyusun laporan kegiatan yang telah dilaksanakan sesuai dengan jadwal yang telah ditentukan;', 'Diutamakan Konsultan dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); Memiliki pendidikan minimal S1 di bidang Ilmu Komputer/Teknik Informatika/Sistem Informasi (dibuktikan dengan ijazah jenjang pendidikan); Memiliki pengalaman minimal 9 (sembilan) tahun sebagai Programmer (dibuktikan dengan surat referensi/kontrak kerja); Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak (dibuktikan dengan surat referensi/kontrak kerja); Memiliki pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS atau Pagu Anggaran (dibuktikan dengan surat referensi/kontrak kerja); Bersedia untuk bekerja di luar jam kerja (lembur) dan dalam jadwal ketat; Memiliki kemampuan yang baik dalam (dibuktikan dengan surat referensi/kontrak kerja): Analisis permasalahan; problem solving; desain sistem berskala besar dan kompleks; mengatur jadwal dan tugas-tugas; Berpengalaman dalam hal (dibuktikan dengan surat referensi/kontrak kerja): membangun sistem berskala besar; membangun sistem informasi web based perencanaan dan penganggaran, khususnya pemerintah daerah; membangun sistem informasi perencanaan dan penganggaran transfer ke daerah skala nasional; membangun Custom Business Intelligence; membangun sistem monitoring pelaporan instansi pemerintah bekerjasama dengan Pemerintah Pusat maupun Pemerintah Daerah; bekerja dengan framework MVC; bekerja dengan metodologi Agile; bekerja dengan API services; bekerja dengan Object Oriented Programming; berkolaborasi dengan IT Developer, Business Intelligence dan Data Team Members. Memiliki penguasaan terhadap hal-hal sebagai berikut (dibuktikan dengan Portofolio (Laporan pekerjaan atau screenshot aplikasi) dan/atau sertifikasi keahlian (SKA/Sertifikat Kompetensi)):', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1478526);
