INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64349362', 64349362, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'KONSULTAN SENIOR SYSTEM ANALYST PENYUSUNAN ANALISIS SISTEM INFORMASI KRISNA PEMERINTAH PUSAT', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 192000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Mengidentifikasikan kebutuhan pengembangan Sistem Informasi KRISNA Pemerintah Pusat, khususnya terkait Penyusunan RKP, Pagu Indikatif, Pagu Anggaran, Pagu Alokasi Anggaran, Integrasi KRISNA-SAKTI Tahun Anggaran 2027, Integrasi KRISNA - eMonev Bappenas, serta kebutuhan pengembangan aplikasi umum perencanaan; Merancang arsitektur, sub sistem, dan rancangan data serta diagram alur yang akan diterapkan pada Penyusunan RKP, Pagu Indikatif, Pagu Anggaran, Pagu Alokasi Anggaran, dan Integrasi KRISNA-SAKTI Tahun Anggaran 2027, Integrasi KRISNA-eMonev, serta kebutuhan pengembangan aplikasi umum perencanaan; Bekerjasama dengan tim pemrograman dan tim pengembangan lainnya dalam penyempurnaan dan pengembangan KRISNA Pemerintah Pusat khususnya terkait Penyusunan RKP, Pagu Indikatif, Pagu Anggaran, Pagu Alokasi Anggaran, Integrasi KRISNA-eMonev Bappenas, dan Integrasi KRISNA-SAKTI Tahun Anggaran 2027 serta kebutuhan pengembangan aplikasi umum perencanaan; Berkoordinasi dengan Konsultan Senior System Analyst KRISNA Daerah untuk melakukan sinkronisasi perencanaan dan penganggaran Pusat dan Daerah; Mengembangkan Sistem Informasi KRISNA Pemerintah Pusat, turut berkontribusi dalam pengembangan Integrasi KRISNA-eMonev, modul Sinkronisasi Renja-RKA pada SAKTI dan menambah fitur baru pada sistem informasi yang telah ada; Melakukan pengujian pada Sistem Informasi KRISNA Pemerintah Pusat kaitannya dalam Penyusunan RKP, Pagu Indikatif, Pagu Anggaran, Pagu Alokasi Anggaran, Integrasi KRISNA-eMonev, dan Integrasi KRISNA-SAKTI; Menyusun dokumentasi sistem (technical documentation) seluruh modul dan fitur pengembangan Sistem Informasi KRISNA Pemerintah Pusat, serta melaksanakan technical training dan knowledge transfer kepada administrator sistem dan key user terkait konfigurasi, alur data, integrasi sistem, serta prosedur pengujian dan troubleshooting; Merancang dan mengimplementasikan mekanisme teknis sinkronisasi data perencanaan dan penganggaran Pemerintah Daerah dengan Sistem Informasi KRISNA Pemerintah Pusat, termasuk penyusunan spesifikasi interface/API, standar struktur data, skema interoperabilitas, serta prosedur validasi dan rekonsiliasi data lintas sistem.', 'Diutamakan Konsultan dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); Memiliki pendidikan minimal S1 di bidang Ilmu Komputer/Teknik Informatika/Sistem Informasi (dibuktikan dengan ijazah jenjang pendidikan); Pengalaman kerja minimal 4 (empat) tahun sebagai analis dalam sistem perencanaan dan penganggaran, baik berbasis sistem aplikasi maupun non aplikasi (dibuktikan dengan surat referensi/kontrak kerja); Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak (dibuktikan dengan surat referensi/kontrak kerja); Memiliki pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS atau Pagu Anggaran (dibuktikan dengan surat referensi/kontrak kerja); Memiliki kemampuan yang baik dan berpengalaman dalam menganalisis, merancang, serta membangun Sistem Informasi Perencanaan dan Penganggaran (Pemerintah Pusat), pengalaman berkoordinasi dengan stakeholders terkait baik Pemerintah Pusat dan Pemerintah Daerah (dibuktikan dengan Portofolio (Laporan pekerjaan atau screenshot aplikasi) dan/atau sertifikasi keahlian (SKA/Sertifikat Kompetensi))', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1479042);
