INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64349990', 64349990, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'KONSULTAN SENIOR SYSTEM ANALYST PENYUSUNAN ANALISIS SISTEM INFORMASI KRISNA PEMERINTAH DAERAH', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 219000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Mengidentifikasi kebutuhan pengembangan Sistem Informasi KRISNA Pemerintah Daerah, khususnya terkait penyusunan DAK Fisik, DAK Nonfisik, Forum Perencanaan Pusat-Daerah (Rakortek dan Musrenbangnas), DAK Aspirasi, dan DAK Persiapan, Integrasi dengan OMSPAN, ALADIN, SIKD, SIPD, dan Aplikasi K/L lainnya dan Aplikasi K/L, serta kebutuhan pengembangan aplikasi umum perencanaan; Merancang arsitektur, sub sistem, rancangan data, rancangan aplikasi, dan diagram alur pengembangan Sistem Informasi KRISNA Pemerintah Daerah, khususnya terkait penyusunan DAK Fisik, DAK Nonfisik, Forum Perencanaan Pusat-Daerah (Rakortek dan Musrenbangnas), DAK Aspirasi, dan DAK Persiapan, Integrasi dengan OMSPAN, ALADIN, SIKD, SIPD, dan Aplikasi K/L lainnyadan Aplikasi K/L, serta kebutuhan pengembangan aplikasi umum perencanaan; Bekerjasama dengan tim pemrograman dan tim pengembangan lainnya dalam penyempurnaan dan pengembangan Sistem Informasi KRISNA Pemerintah Daerah, khususnya terkait penyusunan perencanaan DAK Fisik, DAK Nonfisik, Forum Perencanaan Pusat-Daerah (Rakortek dan Musrenbangnas), DAK Aspirasi, dan DAK Persiapan, Integrasi dengan OMSPAN, ALADIN, SIKD, SIPD, dan Aplikasi K/L, serta kebutuhan pengembangan aplikasi umum perencanaan; Bekerjasama dengan Konsultan Senior System Analyst KRISNA Pusat dalam rangka pelaksanaan sinkronisasi perencanaan dan penganggaran Pusat dan Daerah; Mengembangkan Sistem Informasi KRISNA Pemerintah Daerah, khususnya terkait penyusunan DAK Fisik, DAK Nonfisik, Forum Perencanaan Pusat-Daerah (Rakortek dan Musrenbangnas), DAK Aspirasi, dan DAK Persiapan, Integrasi dengan OMSPAN, ALADIN, SIKD, SIPD, dan Aplikasi K/L lainnya, serta kebutuhan pengembangan aplikasi umum perencanaan dan menambah fitur baru pada sistem informasi yang telah ada; Melakukan pengujian pada pengembangan Sistem Informasi KRISNA Pemerintah Daerah, khususnya terkait penyusunan DAK Fisik, DAK Nonfisik, Forum Perencanaan Pusat-Daerah (Rakortek dan Musrenbangnas), DAK Aspirasi, dan DAK Persiapan, Integrasi dengan OMSPAN, ALADIN, SIKD, SIPD, dan Aplikasi K/L lainnya, serta kebutuhan pengembangan aplikasi umum perencanaan; Menyusun dokumentasi sistem (technical documentation) seluruh modul dan fitur pengembangan Sistem Informasi KRISNA Pemerintah Daerah, serta melaksanakan technical training dan knowledge transfer kepada administrator sistem dan key user terkait konfigurasi, alur data, integrasi sistem, serta prosedur pengujian dan troubleshooting; Merancang dan mengimplementasikan mekanisme teknis sinkronisasi data perencanaan dan penganggaran Pemerintah Daerah dengan Sistem Informasi KRISNA Pemerintah Pusat, termasuk penyusunan spesifikasi interface/API, standar struktur data, skema interoperabilitas, serta prosedur validasi dan rekonsiliasi data lintas sistem', 'Diutamakan Konsultan dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); Memiliki pendidikan minimal S1 di bidang Ilmu Komputer/Teknik Informatika/Sistem Informasi (dibuktikan dengan ijazah jenjang pendidikan); Pengalaman kerja minimal 4 (empat) tahun sebagai analis dalam sistem perencanaan dan penganggaran, baik berbasis sistem aplikasi maupun non aplikasi (dibuktikan dengan surat referensi/kontrak kerja); Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak (dibuktikan dengan surat referensi/kontrak kerja); Memiliki pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS atau Pagu Anggaran (dibuktikan dengan surat referensi/kontrak kerja); Memiliki kemampuan yang baik dan berpengalaman dalam menganalisis, merancang, serta membangun Sistem Informasi Perencanaan dan Penganggaran (Pemerintah Daerah), pengalaman berkoordinasi dengan stakeholders terkait baik Pemerintah Pusat dan Pemerintah Daerah (dibuktikan dengan Portofolio (Laporan pekerjaan atau screenshot aplikasi) dan/atau sertifikasi keahlian (SKA/Sertifikat Kompetensi)).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1479779);
